"""Binary min-heap of comparable items."""


class Heap:
    def __init__(self):
        self.items = []

    def __len__(self):
        return len(self.items)

    def push(self, item):
        h = self.items
        h.append(item)
        i = len(h) - 1
        while i > 1 and h[i] < h[(i - 1) // 2]:
            h[i], h[(i - 1) // 2] = h[(i - 1) // 2], h[i]
            i = (i - 1) // 2

    def pop(self):
        h = self.items
        top, last = h[0], h.pop()
        if h:
            h[0] = last
            i, n = 0, len(h)
            while 2 * i + 1 < n:
                child = 2 * i + 1
                if child + 1 < n and h[child + 1] < h[child]:
                    child += 1
                if h[child] < h[i]:
                    h[i], h[child] = h[child], h[i]
                    i = child
                else:
                    break
        return top

